### Java

```java
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int R = in.nextInt();   // 高度
        int C = in.nextInt();   // 宽度
        int M = in.nextInt();

        Set<Integer> pos = new HashSet<>();  // 截距 b = y - x （斜率 1）
        Set<Integer> neg = new HashSet<>();  // 截距 b = y + x （斜率 -1）

        for (int i = 0; i < M; i++) {
            int x1 = in.nextInt();
            int y1 = in.nextInt();
            int x2 = in.nextInt();
            int y2 = in.nextInt();
            // 判断斜率符号：斜率1时乘积为正，-1时乘积为负
            if ((x2 - x1) * (y2 - y1) > 0) {
                int b = y1 - x1;
                pos.add(b);
            } else {
                int b = y1 + x1;
                neg.add(b);
            }
        }

        int cntCross = 0;
        for (int b1 : pos) {
            for (int b2 : neg) {
                double x = (b2 - b1) / 2.0;
                double y = (b1 + b2) / 2.0;
                if (x > 0 && x < C && y > 0 && y < R) {
                    cntCross++;
                }
            }
        }

        int ans = pos.size() + neg.size() + 1 + cntCross;
        System.out.println(ans);
    }
}
